package jp.personal.hanshinedge.validation;
import android.content.Context;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import org.junit.*;import org.junit.runner.RunWith;import org.json.*;import java.time.*;import jp.personal.hanshinedge.prospective.*;import static org.junit.Assert.*;
@RunWith(AndroidJUnit4.class)public class ProspectiveRuntimeTest {
 static Context c(){return InstrumentationRegistry.getInstrumentation().getTargetContext();}
 static void clear(String p){for(String s:new String[]{"fetch","timechain","result","shadow","formal-buy","settlement"})c().deleteDatabase(p+"-"+s+".db");}
 public static JSONObject race(long start)throws Exception{return new JSONObject().put("date",Instant.ofEpochMilli(start).atZone(ZoneId.of("Asia/Tokyo")).toLocalDate().toString()).put("venue_code","09").put("venue","阪神").put("meeting",1).put("day",1).put("race_no",1).put("source_identity_verified",true).put("scheduled_start",Instant.ofEpochMilli(start).toString()).put("obstacle",false).put("runners",new JSONArray().put(new JSONObject().put("horse_no",1).put("win_odds",2.0)).put(new JSONObject().put("horse_no",2).put("win_odds",5.0)));}
 public static JSONObject receipt(long now,long mono)throws Exception{return new JSONObject().put("http_status",200).put("raw_sha256",String.format("%064d",1)).put("source_record_id","TEST_ONLY_SOURCE").put("source_retrieved_at",Instant.ofEpochMilli(now).toString()).put("received_at_ms",now).put("received_elapsed_ms",mono).put("server_time_ms",now).put("test_only",true);}
 interface Checked{void run()throws Exception;}static void fails(String why,Checked task)throws Exception{try{task.run();fail(why);}catch(Exception e){assertTrue(e.toString(),e.toString().contains(why));}}
 @Test public void canonicalClockAndRegistration()throws Exception{long now=System.currentTimeMillis(),mono=10000;JSONObject raw=race(now+1200000),proof=receipt(now,mono);String id=ProspectiveRuntime.canonical(raw);assertEquals(id,ProspectiveRuntime.canonical(new JSONObject(raw.toString())));assertEquals(12,id.length());org.json.JSONArray preserved=new JSONObject(new java.util.Scanner(InstrumentationRegistry.getInstrumentation().getContext().getAssets().open("jra-real-historical-fixture-20260919-20261114.json"),"UTF-8").useDelimiter("\\A").next()).getJSONArray("races");for(int i=0;i<preserved.length();i++)assertEquals(preserved.getJSONObject(i).getString("race_id"),ProspectiveRuntime.canonical(preserved.getJSONObject(i)));assertTrue(ProspectiveRuntime.clock(proof,now,mono).getBoolean("verified"));assertFalse(ProspectiveRuntime.clock(receipt(now,mono).put("server_time_ms",now-10001),now,mono).getBoolean("verified"));clear("test-registration");try(ProspectiveRuntime r=new ProspectiveRuntime(c(),"test-registration")){assertTrue(r.register(raw,proof,now,mono).getBoolean("REAL_PROSPECTIVE"));assertEquals("DUPLICATE",r.register(raw,proof,now,mono).getString("registration_result"));assertEquals(1,r.registrations().length());}clear("test-late");try(ProspectiveRuntime r=new ProspectiveRuntime(c(),"test-late")){JSONObject out=r.register(race(now-1),proof,now,mono);assertFalse(out.getBoolean("REAL_PROSPECTIVE"));assertEquals("LATE_REGISTRATION",out.getString("reason"));}clear("test-clock");try(ProspectiveRuntime r=new ProspectiveRuntime(c(),"test-clock")){JSONObject out=r.register(raw,new JSONObject(proof.toString()).put("server_time_ms",0),now,mono);assertFalse(out.getBoolean("REAL_PROSPECTIVE"));assertEquals("CLOCK_UNVERIFIED",out.getString("reason"));}clear("test-known");try(ProspectiveRuntime r=new ProspectiveRuntime(c(),"test-known")){assertEquals("RESULT_ALREADY_KNOWN",r.register(new JSONObject(raw.toString()).put("result_known",true),proof,now,mono).getString("reason"));}}
 @Test public void allFourMilestonesDuplicatesConflictAndReopen()throws Exception{long now=System.currentTimeMillis(),start=now+1200000,mono=1000;JSONObject raw=race(start);String id=ProspectiveRuntime.canonical(raw);clear("test-timechain");try(ProspectiveRuntime r=new ProspectiveRuntime(c(),"test-timechain")){r.register(raw,receipt(now,mono),now,mono);for(int i=0;i<4;i++){long at=start-ProspectiveRuntime.TARGET[i]*1000L;JSONObject proof=receipt(at,mono);assertEquals("APPENDED",r.capture(id,ProspectiveRuntime.STAGE[i],raw,proof,at,mono).getString("result"));assertEquals("DUPLICATE",r.capture(id,ProspectiveRuntime.STAGE[i],raw,proof,at,mono).getString("result"));}JSONObject altered=race(start);altered.getJSONArray("runners").getJSONObject(0).put("win_odds",3.0);fails("AUDIT_KEY_CONFLICT",()->r.capture(id,"T-20",altered,receipt(now,mono),now,mono));assertEquals(4,r.runtime.timechainStatus().getInt("count"));}try(ProspectiveRuntime r=new ProspectiveRuntime(c(),"test-timechain")){assertEquals(4,r.runtime.timechainStatus().getInt("count"));assertEquals("DUPLICATE",r.capture(id,"T-20",raw,receipt(now,mono),now,mono).getString("result"));}}
 @Test public void settlementAggregationUsesExistingRuntime()throws Exception{long now=System.currentTimeMillis(),start=now+1200000;JSONObject raw=race(start);String id=ProspectiveRuntime.canonical(raw);clear("test-money");try(ProspectiveRuntime r=new ProspectiveRuntime(c(),"test-money")){r.register(raw,receipt(now,1000),now,1000);JSONObject buy=new JSONObject().put("race_id",id).put("data_status","PROSPECTIVE").put("paper",true).put("result_known",false).put("model_tag",jp.personal.hanshinedge.runtime.CapabilityGate.FROZEN_MODEL).put("realMoney","BLOCKED").put("horse_no",1).put("stake_yen",100);r.runtime.appendFormalPaperBuy(r.context(raw,true,false),"TEST_ONLY",buy.toString(),r.runtime.formalBuyStatus().getString("head"));JSONObject result=new JSONObject().put("race_id",id).put("source_identity_verified",true).put("finish_position",new JSONArray().put(new JSONObject().put("horse_no",1).put("finish_position",1))).put("winner",new JSONArray().put(1)).put("win_payout",new JSONArray().put(new JSONObject().put("horse_no",1).put("payout_per_100",240)));JSONObject proof=receipt(start+60000,1000);assertEquals("APPENDED",r.result(id,result,proof).getString("result"));assertEquals("DUPLICATE",r.result(id,result,proof).getString("result"));RuntimeWorker.settleExisting(r,id);RuntimeWorker.settleExisting(r,id);assertEquals(100140,r.bankroll().getLong("current_bankroll"));assertEquals(140,r.bankroll().getLong("profit_loss"));assertEquals(0,r.bankroll().getInt("pending_count"));assertEquals(1,r.runtime.settlementStatus().getInt("count"));}try(ProspectiveRuntime r=new ProspectiveRuntime(c(),"test-money")){RuntimeWorker.settleExisting(r,id);assertEquals(100140,r.bankroll().getLong("current_bankroll"));assertEquals(1,r.runtime.settlementStatus().getInt("count"));}}
 @Test public void unavailableNoSubstitutionAndNoStakeRule()throws Exception{long now=System.currentTimeMillis();JSONObject raw=race(now+1200000);String id=ProspectiveRuntime.canonical(raw);clear("test-unavailable");try(ProspectiveRuntime r=new ProspectiveRuntime(c(),"test-unavailable")){r.register(raw,receipt(now,1000),now,1000);JSONObject missing=race(now+1200000);missing.getJSONArray("runners").getJSONObject(0).remove("win_odds");assertEquals("ODDS_INCOMPLETE",r.capture(id,"T-20",missing,receipt(now,1000),now,1000).getJSONObject("snapshot").getString("status"));assertEquals("NOT_AVAILABLE",r.bankroll().getString("STAKE_RULE"));assertEquals(0,r.runtime.formalBuyStatus().getInt("count"));assertEquals("OUTSIDE_FIXED_TOLERANCE",r.capture(id,"T-2",raw,receipt(now,1000),now,1000).getJSONObject("snapshot").getString("status"));assertEquals(2,r.runtime.timechainStatus().getInt("count"));}}
 @Test public void futureReceiptAndHistoricalMarketRejected()throws Exception{long now=System.currentTimeMillis();JSONObject raw=race(now+1200000);String id=ProspectiveRuntime.canonical(raw);clear("test-leakage");try(ProspectiveRuntime r=new ProspectiveRuntime(c(),"test-leakage")){fails("SOURCE_RECEIPT_TIME_MISMATCH",()->r.register(raw,receipt(now,1000).put("source_retrieved_at",Instant.ofEpochMilli(now+1000).toString()),now,1000));r.register(raw,receipt(now,1000),now,1000);fails("POST_RESULT_MARKET_FORBIDDEN",()->r.capture(id,"T-20",new JSONObject(raw.toString()).put("data_status","HISTORICAL_REPLAY_ONLY"),receipt(now,1000),now,1000));assertEquals(0,r.runtime.timechainStatus().getInt("count"));assertEquals(0,r.runtime.formalBuyStatus().getInt("count"));}}

}
